"""When DO two G-sets decouple?  The independence criterion in action.

For two sets X and Y carrying an action of the same group G, the orbits of G on the
product X x Y are exactly the products orbit(x) x orbit(y) if and only if every point
stabiliser G_x remains transitive on every G-orbit of Y.  Taking Y = X collapses the
criterion, because a stabiliser cannot move the point it stabilises -- which is why a
G-set is never independent of itself unless the action is trivial.

This script builds several pairs (X, Y) of G-sets for a common group G, tests both sides
of the criterion by brute force, and confirms that they always agree.  It also displays
the diagonal case Y = X, where independence collapses onto triviality.
"""

from __future__ import annotations

from itertools import product
from typing import Callable, Dict, List, Sequence, Tuple

Perm = Tuple[int, ...]


def cycles(n: int, cycs: Sequence[Sequence[int]]) -> Perm:
    """The permutation of {0,...,n-1} given by a product of disjoint cycles."""
    image = list(range(n))
    for c in cycs:
        for i, p in enumerate(c):
            image[p] = c[(i + 1) % len(c)]
    return tuple(image)


def closure(n: int, gens: Sequence[Perm]) -> List[Perm]:
    """Close a set of permutations under composition."""
    ident: Perm = tuple(range(n))
    seen, frontier = {ident}, [ident]
    while frontier:
        new: List[Perm] = []
        for e in frontier:
            for g in gens:
                c = tuple(g[e[i]] for i in range(n))
                if c not in seen:
                    seen.add(c)
                    new.append(c)
        frontier = new
    return sorted(seen)


# An action of an abstract group G on a set of size m is a map G -> permutations of m.
Action = Callable[[Perm], Perm]


def orbits_of(action: Action, group: Sequence[Perm], m: int) -> List[List[int]]:
    seen = [False] * m
    out: List[List[int]] = []
    for x in range(m):
        if seen[x]:
            continue
        o = sorted({action(g)[x] for g in group})
        for y in o:
            seen[y] = True
        out.append(o)
    return out


def products_of_orbits_equal_orbitals(action_x: Action, action_y: Action,
                                      group: Sequence[Perm], mx: int, my: int) -> bool:
    """Test directly whether every orbit on X x Y is a product of orbits."""
    for x, y in product(range(mx), range(my)):
        pair_orbit = {(action_x(g)[x], action_y(g)[y]) for g in group}
        orbit_x = {action_x(g)[x] for g in group}
        orbit_y = {action_y(g)[y] for g in group}
        if pair_orbit != set(product(orbit_x, orbit_y)):
            return False
    return True


def stabilisers_stay_transitive(action_x: Action, action_y: Action,
                                group: Sequence[Perm], mx: int, my: int) -> bool:
    """Test whether every stabiliser G_x is transitive on every G-orbit of Y."""
    for x in range(mx):
        stab = [g for g in group if action_x(g)[x] == x]
        for y in range(my):
            small = {action_y(g)[y] for g in stab}
            big = {action_y(g)[y] for g in group}
            if small != big:
                return False
    return True


def main() -> None:
    # G = Klein four-group, presented as permutations of 4 points.
    n = 4
    group = closure(n, [cycles(n, [[0, 1], [2, 3]]), cycles(n, [[0, 2], [1, 3]])])

    def natural(g: Perm) -> Perm:
        """The defining action on 4 points."""
        return g

    def trivial_on_3(_g: Perm) -> Perm:
        """The trivial action on 3 points."""
        return (0, 1, 2)

    def quotient_pair(g: Perm) -> Perm:
        """The action on the 2-element set of blocks {{0,1},{2,3}}."""
        return (0, 1) if g[0] in (0, 1) else (1, 0)

    cases: List[Tuple[str, Action, int, Action, int]] = [
        ("X = 4 points (natural),  Y = 3 points (trivial)", natural, 4, trivial_on_3, 3),
        ("X = 3 points (trivial),  Y = 4 points (natural)", trivial_on_3, 3, natural, 4),
        ("X = 4 points (natural),  Y = 2 blocks", natural, 4, quotient_pair, 2),
        ("X = 2 blocks,            Y = 4 points (natural)", quotient_pair, 2, natural, 4),
        ("X = Y = 4 points (natural)  [diagonal case]", natural, 4, natural, 4),
        ("X = Y = 3 points (trivial)  [diagonal case]", trivial_on_3, 3, trivial_on_3, 3),
    ]

    print("Independence criterion for two G-sets (G = Klein four-group)")
    print("-" * 86)
    print(f"{'case':52s} {'orbits factor?':>15s} {'stabilisers transitive?':>24s}")
    results: Dict[str, bool] = {}
    for label, ax, mx, ay, my in cases:
        factors = products_of_orbits_equal_orbitals(ax, ay, group, mx, my)
        stabs = stabilisers_stay_transitive(ax, ay, group, mx, my)
        assert factors == stabs, "independence criterion failed"
        results[label] = factors
        print(f"{label:52s} {str(factors):>15s} {str(stabs):>24s}")

    print("\nReadings:")
    print("* Independence holds whenever one of the two sides is acted on trivially:")
    print("  pinning a point of X then costs nothing on Y.")
    print("* It fails as soon as both sides move, e.g. X = 4 points and Y = 2 blocks:")
    print("  a stabiliser of a point of X already knows which block the point lies in.")
    print("* On the diagonal (Y = X) independence holds only in the trivial row --")
    print("  a G-set is never independent of itself unless the action is trivial.")


if __name__ == "__main__":
    main()

