"""Explicit construction of the orbital partition by diagonal orbit propagation."""

from __future__ import annotations

from typing import Dict, List, Sequence, Tuple

Perm = Tuple[int, ...]


def cycles(n: int, cycs: Sequence[Sequence[int]]) -> Perm:
    """The permutation of {0,...,n-1} given as a product of disjoint cycles."""
    image = list(range(n))
    for c in cycs:
        for i, p in enumerate(c):
            image[p] = c[(i + 1) % len(c)]
    return tuple(image)


def closure(n: int, gens: Sequence[Perm]) -> List[Perm]:
    """Close a set of permutations of n points under composition."""
    ident: Perm = tuple(range(n))
    seen, frontier = {ident}, [ident]
    while frontier:
        new: List[Perm] = []
        for e in frontier:
            for g in gens:
                c = tuple(g[e[i]] for i in range(n))
                if c not in seen:
                    seen.add(c)
                    new.append(c)
        frontier = new
    return sorted(seen)


def orbital_partition(group: Sequence[Perm], n: int) -> Tuple[List[List[int]], int]:
    """Label every ordered pair by the index of its orbital.

    Sweeping the pairs in lexicographic order, each unlabelled pair opens a new orbital
    and its entire diagonal orbit {(g(x), g(y)) : g in G} is stamped with the new label.
    Because orbits partition X x X, every pair is stamped exactly once as a
    representative and the sweep touches each pair O(1) times per group element, giving
    a total cost of O(|G| n^2) time and O(n^2) space.

    Returns the label matrix and the number of orbitals.
    """
    label = [[-1] * n for _ in range(n)]
    count = 0
    for x in range(n):
        for y in range(n):
            if label[x][y] >= 0:
                continue
            for g in group:
                label[g[x]][g[y]] = count
            count += 1
    return label, count


def orbit_partition(group: Sequence[Perm], n: int) -> Tuple[List[int], int]:
    """Label every point by the index of its orbit.  Cost: O(|G| n)."""
    label = [-1] * n
    count = 0
    for x in range(n):
        if label[x] >= 0:
            continue
        for g in group:
            label[g[x]] = count
        count += 1
    return label, count


def refinement_report(group: Sequence[Perm], n: int) -> Dict[str, object]:
    """Compare the orbital partition with the square of the orbit partition.

    Each orbit block orbit(x) x orbit(y) is a union of orbitals; the report lists, for
    each block, how many orbitals it contains.  The Orbital Rigidity Theorem says every
    block is a single orbital only for the trivial action, and the total excess over the
    r^2 blocks is exactly the rigidity defect s - r^2.
    """
    olab, r = orbit_partition(group, n)
    slab, s = orbital_partition(group, n)
    pieces: Dict[Tuple[int, int], set] = {}
    for x in range(n):
        for y in range(n):
            pieces.setdefault((olab[x], olab[y]), set()).add(slab[x][y])
    split = {block: len(labels) for block, labels in pieces.items()}
    return {
        "orbit_count": r,
        "orbital_count": s,
        "blocks": r * r,
        "pieces_per_block": split,
        "defect": s - r * r,
        "defect_equals_total_excess": s - r * r == sum(v - 1 for v in split.values()),
        "pair_independent": all(v == 1 for v in split.values()),
    }


if __name__ == "__main__":
    n = 6
    klein = closure(n, [cycles(n, [[0, 1], [2, 3]]), cycles(n, [[2, 3], [4, 5]])])
    labels, s = orbital_partition(klein, n)
    for row in labels:
        print(" ".join(f"{v:2d}" for v in row))
    print(f"orbitals: {s}")
    for key, value in refinement_report(klein, n).items():
        print(f"{key:30s} {value}")
